INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62709724', 62709724, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'BADAN PENDAPATAN DAERAH', 'Jasa Pramu Layanan Umum Petugas Lapangan Verifikasi PBB-P2', 'Jasa Lainnya', 'E-Purchasing', 'Banten, Tangerang (Kota)', 1409670000, 'January 2026', 'APBD', 0, 1, '23 ORANG X 9 BULAN', 'Ruang lingkup Kegiatan Swakelola Jasa Pramu Layanan Umum (Kegiatan Verifikasi PBB-P2) adalah: 1. Melakukan digitasi lokasi objek pajak yang dapat diketahui dan ditemukan; 2. Melakukan pemutakhiran luas bumi dan bangunan, pembetulan alamat, dari objek yang dapat diketahui dan ditemukan; 3. Lokasi kegiatan dilakukan di beberapa wilayah kelurahan yang akan dilakukan pendataan, dengan jumlah kelurahan PBB-P2 minimal sejumlah 8 (delapan) kelurahan yang dapat di tagging.', 'Tahapan pekerjaan yang dilakukan oleh Pramu Layanan Umum Petugas Lapangan Verifikasi PBB-P2 adalah sebagai berikut: a. Membawa data Daftar Hasil Rekaman (DHR) dan Peta yang sudah disiapkan; b. Melakukan digitasi lokasi objek pajak sesuai NOP; c. Melakukan penginputan objek yang di data ke dalam Aplikasi Survey; d. Melakukan pengukuran bangunan jika ada luas bangunan objek bertambah atau bangunan baru didirikan; e. Melaporkan jika terdapat objek di Daftar Hasil Rekaman (DHR) yang tidak dapat ditemukan meski NOP tersebut aktif; f. Melaporkan jika terdapat suatu objek yang ditemukan, namun tidak diketahui atau tidak teridentifikasi dengan jelas di Daftar Hasil Rekaman (DHR); g. Melaporkan jika terdapat objek di Daftar Hasil Rekaman (DHR) yang tidak dapat ditemukan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 755862);
