INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62706765', 62706765, 'analyze_legacy', 'Kota Surakarta', 'kabkota', 'DINAS PERHUBUNGAN', 'Meterisasi PJU Kota Surakarta', 'Pekerjaan Konstruksi', 'Tender', 'Jawa Tengah, Surakarta (Kota)', 35458440000, 'December 2025', 'APBD', 0, 1, '1 Paket', 'Pekerjaan Meterisasi Penerangan Jalan Umum (PJU) Kota Surakarta merupakan kegiatan penataan sistem kelistrikan PJU melalui pemasangan Alat Pembatas dan Pengukur (APP/kWh meter) pada titik-titik PJU yang belum termeterisasi, disertai dengan penggantian lampu eksisting menjadi lampu LED hemat energi, serta pekerjaan jaringan pendukung seperti penambahan tiang bantu, penataan kabel, dan lainnya. Kegiatan ini bertujuan untuk mengalihkan sistem pembayaran listrik dari pola abonemen menjadi berdasarkan daya riil yang terukur, sehingga tercapai efisiensi energi, akurasi data, serta peningkatan tata kelola dan pelayanan penerangan jalan di wilayah Kota Surakarta.', '1. Pemasangan Alat Pembatas dan Pengukur (APP/kWh Meter) sebagai bagian dari pengalihan sistem pembayaran dari abonemen menjadi meterisasi. 2. Pemasangan tiang bantu dan pondasi tiang untuk mendukung penataan jaringan pada titik-titik PJU yang belum memenuhi standar konstruksi. 3. Pemasangan jaringan dan perlengkapan pendukung, meliputi pemasangan asesoris kabel, penarikan kabel jaringan, serta penyambungan dan koneksi ke jaringan lampu eksisting secara aman dan sesuai standar teknis. 4. Penggantian lampu eksisting dengan lampu LED hemat energi yang memiliki efisiensi tinggi dan tingkat pencahayaan sesuai dengan standar penerangan jalan perkotaan. 5. Pelaksanaan perizinan dan sertifikasi, meliputi pengurusan izin dari PLN (BPUJL), Sertifikat Laik Operasi (SLO), dan Nomor Identitas Instalasi (NIDI) sesuai ketentuan peraturan yang berlaku. 6. Pemeriksaan, pengujian, dan komisioning instalasi untuk memastikan seluruh sistem berfungsi dengan baik, aman, dan sesuai spesifikasi teknis. 1. Pemasangan Alat Pembatas dan Pengukur (APP/kWh Meter) sebagai bagian dari pengalihan sistem pembayaran dari abonemen menjadi meterisasi. 2. Pemasangan tiang bantu dan pondasi tiang untuk mendukung penataan jaringan pada titik-titik PJU yang belum memenuhi standar konstruksi. 3. Pemasangan jaringan dan perlengkapan pendukung, meliputi pemasangan asesoris kabel, penarikan kabel jaringan, serta penyambungan dan koneksi ke jaringan lampu eksisting secara aman dan sesuai standar teknis. 4. Penggantian lampu eksisting dengan lampu LED hemat energi yang memiliki efisiensi tinggi dan tingkat pencahayaan sesuai dengan standar penerangan jalan perkotaan. 5. Pelaksanaan perizinan dan sertifikasi, meliputi pengurusan izin dari PLN (BPUJL), Sertifikat Laik Operasi (SLO), dan Nomor Identitas Instalasi (NIDI) sesuai ketentuan peraturan yang berlaku. 6. Pemeriksaan, pengujian, dan komisioning instalasi untuk memastikan seluruh sistem berfungsi dengan baik, aman, dan sesuai spesifikasi teknis.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 756040);
