INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62709721', 62709721, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'POLITEKNIK PERKERETAAPIAN INDONESIA MADIUN', 'Pengadaan Permakanan Taruna Periode Januari - Juni 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Madiun (Kota)', 5007744000, 'January 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 Paket', 'Pengadaan permakanan taruna periode Januari–Juli 2026 merupakan kegiatan penyediaan layanan makan bagi taruna Politeknik Perkeretaapian Indonesia Madiun guna mendukung kelancaran proses pendidikan, pelatihan, dan pembinaan berasrama. Layanan permakanan meliputi penyediaan paket makan pagi, siang, dan malam bagi taruna Tingkat I, Tingkat II, dan Tingkat III sesuai jumlah peserta dan hari pelaksanaan kegiatan pendidikan. Pengadaan ini dilaksanakan untuk memastikan terpenuhinya kebutuhan gizi, kesehatan, serta ketepatan waktu pelayanan permakanan secara berkelanjutan selama periode tersebut.', 'Spesifikasi pekerjaan pengadaan permakanan taruna Periode Januari–Juli 2026 meliputi penyediaan layanan makan tiga kali sehari (makan pagi, siang, dan malam) bagi 740 taruna Politeknik Perkeretaapian Indonesia Madiun yang terdiri atas 308 taruna Tingkat I, 215 taruna Tingkat II, dan 217 taruna Tingkat III, dengan estimasi total volume ±173.000 porsi menggunakan mekanisme kontrak harga satuan. Makanan yang disediakan wajib memenuhi standar gizi seimbang, higienitas, sanitasi, dan kehalalan, menggunakan bahan makanan segar dan layak konsumsi, disajikan tepat waktu, serta diolah di dapur yang berlokasi di lingkungan kampus. Penyedia bertanggung jawab atas kualitas rasa, kecukupan porsi, variasi menu, kebersihan proses pengolahan, pengelolaan limbah, serta pelaksanaan pengawasan mutu secara berkelanjutan untuk mendukung kelancaran pendidikan dan pembinaan taruna selama periode pelaksanaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 757912);
