INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62679974', 62679974, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'KOMISI PENYIARAN INDONESIA', 'Pengadaan Jasa Alih Daya (Outsourcing) Satuan Pengamanan, Pramubkhati, Tenaga Kebersihan, dan Pengemudi KPI Pusat Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 3350380000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'Pengadaan Jasa Alih Daya (Outsourcing) Satuan Pengamanan, Pramubkhati, Tenaga Kebersihan, dan Pengemudi KPI Pusat Tahun Anggaran 2026', 'Supervisor Tenaga Kebersihan (Cleaning Service) Sebanyak 1 (satu) orang selama 12 (dua belas) bulan a. Bertanggung jawab atas seluruh kegiatan operasional tenaga kebersihan b. Mengontrol dan memastikan implementasi kegiatan operasional berjalan sesuai SOP dan aturan. c. Mengontrol dalam memastikan kelengkapan peralatan, chemical dan bahan pendukung lainnya d. Mampu berimprovisasi dan inovatif terkait peningkatan kualitas dan pelayanan e. Melakukan pemeriksaan terhadap absensi kehadiran serta kinerja karyawan f. Merencanakan, menyusun program kerja serta pelatihan (quality design). g. Melakukan briefing dan evaluasi kerja dan bertanggunng jawah atas hasil kerja tenaga kebersihan dan pramubakti h. Memberikan arahan dan intruksi kerja kepada seluruh tenaga kebersihan dan pramubakti i. Menganalisa permasalahan dan mampu memberikan Solusi j. Membuat laporan secara regular. Tenaga Kebersihan (Cleaning Service) sebanyak 7 (tujuh) orang selama 12 (dua belas) bulan 1. Tugas Rutin a. Membersihkan dan merapikan meja,kursi, komputer dan perlengkapan lainnya. b. Melakukan penyapuan (sweeping) lantai agar bebas dari debu dan sampah lepas. c. Melakukan pengepelan (mopping) lantai agar bebas dari noda dan kotoran. d. Melakukan pembersihan toilet secara keseluruhan (general cleaning). e. Melakukan pembersihan entrance/ pintu masuk. f. Membuang sampah yang ada di seluruh area kerja ke TPS. 2. Tugas Berkala a. Melakukan pembersihan kaca (glass cleaning) Ruang kerja. b. Melakukan pembersihan sarang laba laba (web spider cleaning). c. Melakukan Pembersihan aksesoris gedung yg ada di ketinggian (High Dusting) seperti exhaustfan, ac grill dll. d. Melakukan Pembersihan/ pencucian tempat sampah. e. Melakukan Pembersihan/ pencucian nomed/ keset lantai Pramubakti (Office Boy) sebanyak 3 (tiga) orang selama 12 (dua belas) bulan 1. Tugas Rutin a. Melakukan pembersihan area Pantry. b. Membereskan piring, gelas dan perlengkapan makan karyawan c. Mencuci piring, gelas dan perlengkapan makan karyawan d. Membuat minuman untuk karyawan (seperti kopi, air putih dll) e. Membeli makanan untuk karyawan makan siang 2. Tugas Berkala a. Menyediakan minuman/ makanan dan melayani keperluan tamu Perusahaan. b. Menyediakan minuman/ makanan dan melayani keperluan rapat/ pertemuan. c. Mengangkat/ memindahkan meja/ kursi, galon atau perabot lainnya (sesuai permintaan). d. Mengirim/mengambil dokumen antar bagian/divisi. Komandan Regu sebanyak 1 (satu) orang selama 12 (dua belas) bulan a. Melaksanakan pengamanan terhadap aset perusahaan, karyawan dan pihak-pihak terkait yang berhubungan dengan perusahaan agar dapat berjalan dengan baik sesuai dengan Prosedur Tetap (PROTAP) pengamanan yang telah ditetapkan b. Berkewajiban menjaga keamanan dan ketertiban yang berlaku di perusahaan Komisi Penyiaran Indonesia c. Mengecek dan mengontrol serta menjamin semua anggota regu jaga menempati pos penjagaan masing-masing dengan tepat waktu dan memastikan selalu berada di pos penjagaan dalam keadaan siap siaga d. Menjaga kebersihan pos penjagaan dan area sekitarnya e. Mengawasi / memberikan arahan agar anggota satpam melaksanakan tugas dan kewajibannya secara baik dengan penuh tanggung jawab f. Menjaga dan merawat kelengkapan inventaris pos penjagaan sesuai daftar inventaris yang sudah ada g. Bila ada hal-hal atau kejadian yang menonjol dan mencurigakan segera melaporkan ke Dansek h. Memerintahkan anggota satpam apabila sewaktu-waktu dalam pelaksanaan turjawali membutuhkan bantuan perkuatan pengamanan i. Secara aktif melaksanakan segala kebijakan manajemen Komisi Penyiaran Indonesia j. Membuat laporan secara reguler Satuan Pengamanan a. Memastikan keamanan lingkungan kerja yang kondusif b. Menjaga pintu masuk dan keluar untuk mencegah akses oleh pihak yang tidak berwenang c. Melakukan patroli secara rutin untuk memastikan tidak ada aktivitas mencurigakan di area perkantoran d. Melakukan pengecekan ruangan, pengecekan kesiapan alat K3, mengatur lalu lintas kendaraan dan parkir dilingkungan kantor e. Mengawasi monitor CCTV untuk mendeteksi dan merespons ancaman keamanan secara cepat f. Melakukan penjadwalan pelaksanaan piket shift perbulannya g. Memberikan laporan harian mengenai aktivitas dan kejadian yang terjadi selama jam kerja h. Berkoordinasi dengan Danru jika terjadi sesuatu insiden di area perkantoran Satuan Pengamanan Wanita sebanyak 1 (satu) orang selama 12 (dua belas) bulan a. Memastikan keamanan lingkungan kerja yang kondusif b. Memeriksa identitas setiap orang yang masuk dan keluar dari area perkantoran c. Mencatat identitas tamu yang masuk ke dalam gedung perkantoran d. Mengawasi monitor CCTV untuk mendeteksi dan merespons ancaman keamanan secara cepat e. Berkoordinasi dengan Danru jika terjadi sesuatu insiden di area perkantoran Pengemudi sebanyak 10 (sepuluh) orang selama 12 (dua belas) bulan a. Memastikan kelayakan, kebersihan, kelengkapan dan kondisi prima untuk kendaraan dinas pimpinan dan kendaraan operasional perkantoran yang akan digunakan b. Memastikan kenyamanan dan keselamatan penggunaan pemakaian kendaraan dinas selama beroperasi c. Mengecek mesin, oli, dan bensin setiap harinya serta melaporkan apabila ada permasalahan baik kecil ataupun besar yang ditemukan pada kendaraan dinas d. Membuat laporan tertulis secara periodik mengenai penggunaan kendaraan dinas', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 758597);
