INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62710388', 62710388, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA KUALA KURUN 01', 'Pengawas', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Kalimantan Tengah, Gunung Mas (Kab.)', 100000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Keg, @ 100000000 )', 'Pengawas', '1. Lingkup Kegiatan Lingkup kegiatan yang dilaksanakan adalah Jasa Konsultansi Pengawasan Pembangunan Sarana Lingkungan Gedung Kantor Pengadilan Agama Sukamara; 2. Lingkup Tugas A. Pekerjaan Persiapan 1. Menyusun program kerja alokasi tenaga dan konsepsi pekerjaan pengawasan 2. Memeriksa Time Schedule/Bar Chart,S-Curve dan Net Work Planning yang diajukan oleh Kontraktor pelaksana untuk selanjutnya diteruskan kepada pengelola proyek untuk mendapatkan persetujuan B. Uraian Tugas Pekerjaan Teknis pengawasan 1. Melaksanakan pekerjaan pengawasan secara umum, pengawasan lapangan, koordinasi dan inspeksi kegiatan–kegiatan pembangunan agar pelaksanaan teknis maupun administrasi teknis yang dilakukan dapat secara terus menerus sampai dengan pekerjaan diserahkan untuk kedua kalinya. 2. Mengawasi kebenaran ukuran, kualitas dan kuantitas dari bahan atau komponen bangunan, peralatan dan perlengkapan selama pekerjaan pelaksanaan di lapangan atau ditempat kerja lainnya. 3. Mengawasi kemajuan pelaksanaan dan mengambil tindakan yang tepat dan cepat, agar batas waktu pelaksanaan minimal sesuai dengan jadwal yang ditetapkan. 4. Memberikan masukkan pendapat teknis tentang penambahan atau pengurangan biaya dan waktu pekerjaan serta berpengaruh pada ketentuan kontrak, untuk mendapatkan persetujuan dari Pengguna Jasa. 5. Memberikan petunjuk, perintah sejauh tidak mengenai pengurangan dan penambahan biaya dan waktu pekerjaan serta tidak menyimpang dari kontrak, dapat langsung disampaikan kepada pemborong, dengan pemberitahuan tertulis kepada Pengelola Proyek. 6. Memberikan bantuan dan petunjuk kepada Pemborong dalam mengusahakan perijinan sehubungan dengan pelaksanaan pembangunan. C. Konsultasi 1. Melakukan konsultasi ke Pengguna Jasa untuk membahas segala masalah dan persoalan yang timbul selama masa pembangunan. 2. Mengadakan rapat lapangan secara berkala, sedikitnya dua kali dalam sebulan, dengan Pengguna Jasa, perencana dan pemborong dengan tujuan untuk membicarakan masalah dan persoalan yang timbul dalam pelaksanaan, untuk kemudian membuat risalah rapat dan mengirimkan kepada semua Pihak yang bersangkutan, serta sudah diterima paling lambat 1 minggu kemudian. 3. Mengadakan rapat diluar jadwal rutin tersebut apabila dianggap mendesak. D. Laporan. 1. Memberikan Laporan dan pendapat teknis administrasi dan teknis kepada Pengguna Jasa, mengenai volume, prosentase dan nilai bobot bagian-bagian pekerjaan yang akan dilaksanakan oleh Kontraktor Pelaksana. 2. Melaporkan kemajuan pekerjaan yang nyata dilaksanakan dan dibandingkan dengan jadwal yang telah disetujui. 3. Melaporkan bahan-bahan bangunan yang dipakai, jumlah tenaga kerja dan alat yang digunakan. 4. Memeriksa gambar-gambar kerja tambahan yang dibuat oleh pemborong terutama yang mengakibatkan tambah atau berkurangnya pekerjaan, yang dibuat oleh Pemborong (Shop Drawing). E. Dokumen 1. Menyiapkan berita Acara sehubungan dengan penyelesaian pekerjaan di lapangan, serta untuk keperluan pembayaran angsuran. 2. Memeriksa dan menyiapkan daftar volume dan nilai pekerjaan, serta penambahan atau pengurangan pekerjaan guna keperluan pembayaran. 3. Mempersiapkan formulir, laporan harian, mingguan dan bulanan, Berita Acara kemajuan Pekerjaan, Penyerahan Pertama dan Kedua serta formulir-formulir lainnya yang diperlukan untuk kebutuhan dokumen pembangunan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 758983);
