INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62710387', 62710387, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA KUALA KURUN 01', 'Perencana', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Kalimantan Tengah, Gunung Mas (Kab.)', 100000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Keg, @ 100000000 )', 'Perencana', 'Lingkup tugas yang harus dilaksanakan oleh konsultan perencana adalah berpedoman pada ketentuan yang berlaku, khususnya Peraturan Menteri Pekerjaan Umum dan Perumahan Rakyat Nomor : 22/PRT/M/2018 tanggal 14 September 2018 tentang Pembangunan Bangunan Gedung Negara yang dapat meliputi tugas-tugas Perencanaan Sarana Lingkungan Kantor berupa Jalan/Halaman Kantor, Pagar, Taman, pekerjaan instalasi listrik dan air serta pekerjaan lain yang berkaitan dengan pekerjaan perancangan dimaksud. Adapun tahap- tahap perancangan sebagai berikut : a. Persiapan perencanaan seperti mengumpulkan data dan informasi lapangan, membuat interprestasi secara garis besar terhadap KAK, dan konsultasi dengan pemerintah setempat mengenai peraturan daerah/perijinan bangunan. b. Penyusunan Perencanaan seperti pra-rencana dan pengembangan rencana; c. Penyusunan Rencana Detail, antara lain membuat : 1) Gambar-Gambar detail sesuai gambar rencana yang telah disetujui oleh pengguna jasa. Semua gambar Rencana harus ditanda tangani oleh Penanggung jawab perusahaan dan tenaga ahli yang mempunyai ijin Sertfikat. 2) Rancangan Konseptual, DED, dan Dokumen Pemilihan penyedia barang/jasa WAJIB memuat analisis K3; 3) Rencana Kerja dan Syarat-sarat (RKS). 4) Rincian volume pelaksanaan pekerjaan, Rencana anggaran biaya pekerjaan kontruksi (RAB ). 5) Penyusunan RAB wajib memperhitungkan biaya penyelenggaraan SMK3 Konstruksi, masuk dalam item biaya umum; 6) Laporan-laporan perencanaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 759088);
